export const byId=id=>products.find(p=>p.id===id);
export function compatibility(p,width,a){if(!p||!a)return {ok:false,reason:'Choose a cabinet first.'};if(!a.kinds.includes(p.kind))return {ok:false,reason:a.name+' needs '+a.kinds.map(k=>({door:'a door base',narrow:'a narrow base',pantry:'a pantry',utility:'a utility cabinet',drawer:'a drawer base',corner:'a corner base',wall:'a wall cabinet','tall-wall':'a tall wall cabinet'}[k]||k)).join(' or ')+'.'};if(width<a.min||width>a.max)return {ok:false,reason:a.name+' uses a '+a.min+'–'+a.max+' inch wide cabinet in this prototype.'};return {ok:true,reason:'Planning match. Factory must verify the exact accessory and internal clearance.'};}
export function validateConfiguration(c){const p=byId(c.product);if(!p)return 'Choose a cabinet type.';if(!p.widths.includes(Number(c.width))||!p.depths.includes(Number(c.depth))||!p.heights.includes(Number(c.height)))return 'Choose a listed planning size or request a custom-size review.';if(!p.styles.includes(c.style))return 'Choose a door style.';const f=finishes.find(f=>f.id===c.finish);if(!f||!f.doorMaterials.includes(c.doorMaterial)||!p.boxMaterials.includes(c.boxMaterial))return 'Choose a finish, door material and cabinet-box material.';if(!Number.isInteger(Number(c.quantity))||c.quantity<1||c.quantity>99)return 'Choose a quantity from 1 to 99.';for(const id of c.accessories||[]){const a=accessories.find(a=>a.id===id);if(!a||!compatibility(p,Number(c.width),a).ok)return 'Remove an incompatible accessory before continuing.';}return '';}
export function filterProducts(filters){return products.filter(p=>(!filters.category||p.category===filters.category)&&(!filters.width||p.widths.includes(Number(filters.width)))&&(!filters.height||p.heights.includes(Number(filters.height)))&&(!filters.depth||p.depths.includes(Number(filters.depth)))&&(!filters.style||p.styles.includes(filters.style))&&(!filters.finish||p.finishIds.includes(filters.finish))&&(!filters.material||finishes.some(f=>p.finishIds.includes(f.id)&&f.doorMaterials.includes(filters.material)))&&(!filters.price||filters.price==='quote')&&(!filters.storage||p.widths.some(w=>compatibility(p,w,accessories.find(a=>a.id===filters.storage)).ok)));}
export function productSvg(p,{width,style='Shaker',finish='soft-white',technical=false}={}){const color=finishes.find(f=>f.id===finish)?.swatch||'#ecebe4';const tall=p.category==='tall'||p.kind==='tall-wall';const x=tall?78:44,w=tall?84:152,y=20,h=160;let fronts='';const drawer=p.kind==='drawer';for(let i=0;i<(drawer?3:1);i++){const fy=y+6+i*(h-12)/(drawer?3:1),fh=(h-12)/(drawer?3:1)-4;fronts+=`<rect x="${x+6}" y="${fy}" width="${w-12}" height="${fh}" rx="1" fill="${color}" stroke="#656c60"/>${style==='Shaker'?`<rect x="${x+15}" y="${fy+9}" width="${w-30}" height="${Math.max(8,fh-18)}" fill="none" stroke="#8b8b7870"/>`:''}<path d="M${x+w/2-8} ${fy+8}h16" stroke="#746649" stroke-width="3"/>`;}
return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 240" role="img" aria-label="${p.name} ${technical?'dimension diagram':'illustrative cabinet preview'}"><rect width="240" height="240" fill="#eeeee5"/><path d="M${x+w} ${y}l18 -9v${h}l-18 9" fill="#d7d4c7" stroke="#656c60"/><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${color}" stroke="#656c60"/>${fronts}${p.kind==='sink'?`<rect x="${x+8}" y="${y+6}" width="${w-16}" height="22" fill="#d9ddd0"/><text x="120" y="35" text-anchor="middle" font-size="8">Plumbing cavity</text>`:''}${p.kind.includes('corner')?'<path d="M110 26v144 M66 100h43" stroke="#656c60"/>':''}${technical?`<path d="M${x} 200h${w} M${x} 193v14 M${x+w} 193v14" stroke="#626b4f"/><text x="120" y="220" text-anchor="middle" font-size="12">${width||p.widths[0]} W × ${p.depths[0]} D × ${p.heights[0]} H inches</text>`:''}</svg>`;}
